public class Solution {
    public int[] sortedSquares(int[] nums) {
        int n = nums.length;
        int[] r = new int[n];
        int l = 0, h = n-1, w = n-1;
        while (l <= h) {
            int sl = nums[l]*nums[l], sh = nums[h]*nums[h];
            if (sl > sh) { r[w--] = sl; l++; } else { r[w--] = sh; h--; }
        }
        return r;
    }
}
